#include <stdint.h>
#include <stdio.h>
#include <string.h>

static void print_set(uint64_t set) {
    if (set == 0) {
        printf("пусто\n");
        return;
    }
    int first = 1;
    for (int k = 0; k < 64; k++) {
        if ((set >> k) & 1u) {
            printf(first ? "%d" : " %d", k);
            first = 0;
        }
    }
    printf("\n");
}

static int count(uint64_t set) {
    int n = 0;
    for (; set != 0; set &= set - 1) {
        n++;
    }
    return n;
}

int main(void) {
    uint64_t sets[2] = {0, 0};
    char command[16];
    while (scanf("%15s", command) == 1) {
        if (strcmp(command, "union") == 0) {
            print_set(sets[0] | sets[1]);
        } else if (strcmp(command, "inter") == 0) {
            print_set(sets[0] & sets[1]);
        } else if (strcmp(command, "diff") == 0) {
            print_set(sets[0] & ~sets[1]);
        } else if (strcmp(command, "xor") == 0) {
            print_set(sets[0] ^ sets[1]);
        } else {
            char which;
            if (scanf(" %c", &which) != 1) {
                break;
            }
            uint64_t *s = &sets[which == 'A' ? 0 : 1];
            if (strcmp(command, "size") == 0) {
                printf("%d\n", count(*s));
                continue;
            }
            if (strcmp(command, "print") == 0) {
                print_set(*s);
                continue;
            }
            int x;
            if (scanf("%d", &x) != 1 || x < 0 || x > 63) {
                break;
            }
            uint64_t bit = UINT64_C(1) << x;
            if (strcmp(command, "add") == 0) {
                *s |= bit;
            } else if (strcmp(command, "del") == 0) {
                *s &= ~bit;
            } else if (strcmp(command, "has") == 0) {
                printf("%s\n", (*s & bit) != 0 ? "да" : "нет");
            }
        }
    }
    return 0;
}

